from sim import Sim
from solve import PDMotorController
import numpy as np

def simulate(hip_off, ankle_off, steps=800):
    sim=Sim(); ctrl=PDMotorController(sim)
    q=ctrl.q_des.copy()
    # indices
    for idx in (2,7):
        q[idx]+=hip_off
    for idx in (4,9):
        q[idx]+=ankle_off
    ctrl.set_q_des(q)
    min_up=1e9; min_pz=1e9
    for i in range(steps):
        ctrl.step(); sim.step(1)
        if i%20==0:
            min_up=min(min_up, sim.torso_up())
            min_pz=min(min_pz, sim.pelvis_position()[2])
    return float(sim.pelvis_position()[0]), float(min_pz), float(min_up)

for hip_off in (-0.4,-0.2,0.0,0.2,0.4):
    for ankle_off in (-0.2,0.0,0.2):
        x, pz, up = simulate(hip_off, ankle_off)
        ok = (pz>0.74 and up>0.5)
        print(f'hip{hip_off:+.1f} ankle{ankle_off:+.1f} final_x={x:+.3f} min_pz={pz:.3f} min_up={up:.3f} ok={ok}')
