from sim import Sim
from solve import PDMotorController, make_cradle_pose


def test(hip_off, ankle_off, steps=2000):
    sim=Sim(); ctrl=PDMotorController(sim)
    q = make_cradle_pose(ctrl.q_des)
    for idx in (2,7): q[idx]+=hip_off
    for idx in (4,9): q[idx]+=ankle_off
    ctrl.set_q_des(q)
    max_x=-1e9; min_pz=1e9; min_up=1e9; min_bz=1e9; max_d=0
    for i in range(steps):
        ctrl.step(); sim.step(1)
        if i%10==0:
            p=sim.pelvis_position(); b=sim.box_position();
            max_x=max(max_x,p[0]); min_pz=min(min_pz,p[2]); min_up=min(min_up, sim.torso_up());
            min_bz=min(min_bz,b[2]); max_d=max(max_d, sim.box_distance_to_pelvis())
    return max_x, min_pz, min_up, min_bz, max_d, sim.distance_to_target(), sim.box_distance_to_target()

for hip_off, ankle_off in [(-0.4,0.0),(-0.3,0.0),(-0.4,0.1),(-0.5,0.0)]:
