from sim import Sim
from solve import PDMotorController, make_cradle_pose, gait_delta
import numpy as np

def run(scale, steps=2600):
    sim=Sim(); ctrl=PDMotorController(sim)
    base=make_cradle_pose(ctrl.q_des)
    for idx in (2,7): base[idx]+=-0.45
    stable_steps=200
    dt=float(sim.model.opt.timestep)
    max_x=-1e9; min_pz=1e9; min_up=1e9; min_bz=1e9; max_d=0
    for i in range(steps):
        t=i*dt
        q=base.copy()
        if i>=stable_steps:
            q += scale*gait_delta(t-stable_steps*dt)
        ctrl.set_q_des(q)
        ctrl.step(); sim.step(1)
        if i%10==0:
            p=sim.pelvis_position(); b=sim.box_position();
            max_x=max(max_x,p[0]); min_pz=min(min_pz,p[2]); min_up=min(min_up, sim.torso_up());
            min_bz=min(min_bz,b[2]); max_d=max(max_d, sim.box_distance_to_pelvis())
        if min_pz<0.74 or min_up<0.5 or min_bz<0.72 or max_d>0.42:
            # early stop once clearly failing
            if i>400:
                break
    return i, max_x, min_pz, min_up, min_bz, max_d, sim.distance_to_target(), sim.box_distance_to_target()

for scale in [0.15,0.25,0.35,0.45]:
    i, max_x, min_pz, min_up, min_bz, max_d, dp, db = run(scale)
    print('scale',scale,'steps',i,'max_x',max_x,'min_pz',min_pz,'min_up',min_up,'min_bz',min_bz,'max_d',max_d,'dPel',dp,'dBox',db)
PY"

